def solve_refined():
    a1 = 2024
    primes_a1 = {2, 11, 23}
    max_diff = -1
    best_pair = (0, 0)

    for alpha in range(10000, 2024, -1):
        for beta in range(2025, 10001):
            c = alpha + beta
            temp_c = c
            factors = set()
            d = 2
            while d * d <= temp_c:
                if temp_c % d == 0:
                    factors.add(d)
                    while temp_c % d == 0:
                        temp_c //= d
                d += 1
            if temp_c > 1:
                factors.add(temp_c)

            condition_met = True
            for p in factors:
                if p not in primes_a1 and (a1 + alpha) % p != 0:
                    condition_met = False
                    break

            if condition_met:
                diff = alpha - beta
                if diff > max_diff:
                    max_diff = diff
                    best_pair = (alpha, beta)
                break
    return max_diff, best_pair

