import math

def get_prime_factors(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

# Precompute factors for all d up to 20000
factors_dict = {}
for i in range(1, 20001):
    factors_dict[i] = get_prime_factors(i)

# v_p(2024)
v2024 = get_prime_factors(2024)

def solve():
    max_val = -float('inf')
    found_any = False

    # v_p(K) will be needed
    for k in range(4049, 12025):
        vk = get_prime_factors(k)

        # For this k, we want to find smallest d in [k+1, k+7976]
        # such that d | lcm(2024, k)
        # d | lcm(2024, k) <=> for all p^a || d, a <= max(v_p(2024), v_p(k))

        c = None
        for d in range(k + 1, k + 7976 + 1):
            if d > 20000: break

            # Check if d | lcm(2024, k)
            possible = True
            for p, a in factors_dict[d].items():
                v_p_2024 = v2024.get(p, 0)
                v_p_k = vk.get(p, 0)
                if a > max(v_p_2024, v_p_k):
                    possible = False
                    break

            if possible:
                c = d
                break

        if c is not None:
            val = 2 * k - c - 4048
            if val > max_val:
                max_val = val
            found_any = True

    return max_val, found_any

print(solve())

