def solve_correct():
    a1 = 2024
    max_diff = -1
    best_pair = (0, 0)

    for c in range(4050, 20001):
        alpha_max = min(10000, c - 2025)
        alpha_min = max(2025, c - 10000)

        if alpha_max < alpha_min:
            continue

        divisors = []
        for i in range(1, int(c**0.5) + 1):
            if c % i == 0:
                divisors.append(i)
                if i*i != c:
                    divisors.append(c // i)

        D = [d for d in divisors if a1 % d != 0]

        if not D:
            continue

        import math
        from functools import reduce

        def lcm(x, y):
            return abs(x * y) // math.gcd(x, y)

        L = 1
        for d in D:
            L = lcm(L, d)

        # Find largest alpha in [alpha_min, alpha_max] s.t. (alpha + a1) % L == 0
        # alpha + a1 = m*L
        # alpha = m*L - a1
        # We want m*L - a1 <= alpha_max  => m*L <= alpha_max + a1
        # We want m*L - a1 >= alpha_min  => m*L >= alpha_min + a1

        m_max = (alpha_max + a1) // L
        m_min = (alpha_min + a1 + L - 1) // L

        if m_max >= m_min:
            alpha = m_max * L - a1
            diff = alpha - (c - alpha)
            if diff > max_diff:
                max_diff = diff
                best_pair = (alpha, c - alpha)

    return max_diff, best_pair

