import math

def get_lcm(a, b):
    return abs(a * b) // math.gcd(a, b)

def get_divisors(n):
    divs = []
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divs.append(i)
            if i*i != n:
                divs.append(n // i)
    divs.sort()
    return divs

max_val = -float('inf')
best_Y = -1
best_T = -1

for Y in range(4049, 12025):
    lcm_val = get_lcm(2024, Y)
    divs = get_divisors(lcm_val)

    # Find smallest T in [Y+1, Y+7976]
    T = -1
    for d in divs:
        if d > Y:
            if d <= Y + 7976:
                T = d
                break
            else:
                break

    if T != -1:
        val = 2 * Y - T - 4048
        if val > max_val:
            max_val = val
            best_Y = Y
            best_T = T

